findings.codeql_raw_query:
/**
 * @name SSRF via command line arguments
 * @description Traces flow from sys.argv to urllib request
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-argv
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: sys.argv or sys.argv subscript
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: urllib.urlopen or urllib2.urlopen argument
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("urllib").getMember("urlopen").getACall() or
        call = API::moduleImport("urllib2").getMember("urlopen").getACall() or
        call = API::moduleImport("urllib.request").getMember("urlopen").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF from $@.", source.getNode(), "command line argument"
